styleBlocks.source:
#openai-key-dialog,#connection-dialog{width:min(540px,calc(100vw - 32px))}
#openai-key-dialog .row,#openai-connection .row{flex-wrap:wrap;gap:8px}
#openai-key-dialog button,#openai-connection button,#connections [data-storage]{font-size:12px;min-height:30px;padding:6px 10px}
.ai-global-control{display:flex;flex-direction:row;align-items:center;gap:10px;margin:14px 0}
.ai-global-control input{width:16px;height:16px;min-height:16px;margin:0;accent-color:var(--accent,#ffdc24)}
#studio-ai-status{display:flex;align-items:center;gap:12px;justify-content:space-between;font-size:12px;color:var(--muted);margin:0 0 14px}
#studio-ai-status[data-enabled=true]{color:var(--accent,#ffdc24)}
#studio-ai-status button,.ai-prompt-assist{flex:0 0 auto;width:auto;align-self:flex-start;font-size:12px;padding:5px 9px;min-height:28px}
#ai-review-dialog{width:min(760px,calc(100vw - 32px));max-height:85vh;overflow:auto}
#ai-generation-dialog{width:min(620px,calc(100vw - 32px));max-height:85vh;overflow:auto}
#ai-generation-dialog textarea{min-height:150px;line-height:1.5;resize:vertical}
#ai-generation-dialog [hidden]{display:none!important}
#ai-generation-dialog .row{justify-content:flex-end;gap:8px}
#ai-review-dialog details{font-size:12px}#ai-review-dialog textarea{font-size:12px;min-height:120px}
#ai-review-dialog .ai-questions{color:var(--accent,#ffdc24);white-space:pre-wrap}
#ai-review-dialog [hidden],#studio-ai-status [hidden],#openai-connection [hidden]{display:none!important}

#studio-ai-status[hidden]{display:none!important}
#studio-ai-button{color:#fff!important;font-size:12px;padding:5px 9px;min-height:28px;background:transparent}
#studio-ai-button[data-connected=true]{color:var(--accent,#ffdc24)!important}
body.workspace-entry-mode #studio-ai-button{display:none!important}

#studio-ai-button,#studio-storage-indicator{display:inline-flex;align-items:center;justify-content:center;width:28px;height:28px;padding:0;font-size:20px;flex:none;color:#fff!important;cursor:default}
#studio-ai-button[data-connected=true],#studio-storage-indicator[data-connected=true]{color:var(--accent,#ffdc24)!important}
body.workspace-entry-mode #studio-storage-indicator{display:none!important}
#connect-storage[hidden],#reconnect-gpu[hidden]{display:none!important}

#connection-indicators{display:inline-flex;align-items:center;gap:8px;padding:4px 10px;border:1px solid rgba(190,180,215,.22);border-radius:10px;background:linear-gradient(180deg,#302a43,#242031);box-shadow:inset 0 1px 3px rgba(0,0,0,.35),0 1px 0 rgba(255,255,255,.04);flex:none}
#connection-indicators>span{width:24px;height:26px;min-height:26px}
body.workspace-entry-mode #connection-indicators{display:none!important}
#connections .connection{padding:16px 0;border-bottom:1px solid rgba(190,180,215,.15)}
#connections .connection:last-child{border-bottom:0}
#connections .connection-heading{display:flex;align-items:center;justify-content:space-between;gap:16px}
#connections .connection-heading h3{margin:0}
#connection-dialog button{box-sizing:border-box;width:112px!important;min-height:32px!important;height:32px!important;padding:5px 10px!important;font-size:12px!important;white-space:nowrap}
#connections button[data-connected=true]{color:var(--accent,#ffdc24)!important;border-color:var(--accent,#ffdc24)!important}
#connections .help{margin:8px 0 0;line-height:1.5}
#connections [data-ai-disconnect]{margin-left:auto;display:block}

#connection-dialog > .section-head > h2{font-size:18px;color:var(--accent,#ffdc24)}

#connection-panel-menu>summary{min-height:26px;padding:0 4px;justify-content:center}
#connection-panel-menu{margin-left:2px}
[data-category="Account"] [data-category="Billing"]>.workspace-menu-items{position:static;box-shadow:none;border:0;min-width:0}

/* Keep AI assistance beside the field label, without adding another panel. */
.ai-prompt-toolbar{display:flex;align-items:center;justify-content:space-between;gap:12px;width:100%;min-width:0}
.ai-prompt-label{min-width:0}
.ai-prompt-toolbar>.ai-prompt-assist{align-self:center;margin:0;padding:3px 7px;min-height:24px;line-height:1.3;font-size:11px;font-weight:500;white-space:nowrap;border:1px solid transparent;background:transparent;box-shadow:none;color:var(--muted,#b8b0cd)}
.ai-prompt-toolbar>.ai-prompt-assist:hover,.ai-prompt-toolbar>.ai-prompt-assist:focus-visible{color:var(--accent,#ffdc24);border-color:var(--accent,#ffdc24);background:#38305e}
.ai-prompt-toolbar>.ai-prompt-assist:disabled{opacity:.55}
#ai-review-dialog [data-suggestion]{min-height:180px;resize:vertical;line-height:1.5}
#ai-review-dialog .ai-review-notes{white-space:pre-wrap}
#ai-review-dialog [data-apply-status]{color:var(--accent,#ffdc24)}
#ai-review-dialog .row{justify-content:flex-end;gap:8px}
@media(max-width:480px){.ai-prompt-toolbar{gap:6px}.ai-prompt-toolbar>.ai-prompt-assist{font-size:10px;padding:3px 5px}}

#story-entry-panel{display:flex;justify-content:flex-end;align-items:center;gap:6px;margin:0 0 16px auto;padding:5px 8px;width:fit-content;max-width:100%;border:1px solid rgba(190,180,215,.22);border-radius:10px;background:linear-gradient(180deg,#302a43,#242031);box-shadow:inset 0 1px 3px rgba(0,0,0,.35);flex-wrap:wrap}
#story-entry-panel>button,#story-entry-panel>details>summary{box-sizing:border-box;font-size:12px!important;min-height:30px!important;height:30px;padding:5px 10px!important;margin:0}
#story-entry-panel [aria-pressed=true],#story-entry-panel details[open]>summary{color:var(--accent,#ffdc24)!important}
#story-entry-panel .workspace-menu-items .row{display:flex;flex-direction:column;align-items:stretch;gap:6px}
#story-pdf-tools[hidden]{display:none!important}

:is(#page,#video-shot-controls,#video-audio-script) .ai-selected-field{border-color:var(--accent,#ffdc24)!important;outline:1px solid var(--accent,#ffdc24);outline-offset:1px}
:is(#storyboard-ai-toolbar,#story-description-ai,#video-flow-ai)>button{flex:0 0 auto;width:auto}

:is(#storyboard-ai-toolbar,#story-description-ai,#video-flow-ai).storyboard-ai-floating{position:fixed;right:24px;bottom:28px;z-index:110}
:is(#storyboard-ai-toolbar,#story-description-ai,#video-flow-ai)>summary{list-style:none;display:grid;place-items:center;width:44px;height:44px;border:1px solid var(--accent,#ffdc24);border-radius:50%;background:#252039;color:var(--accent,#ffdc24);font-weight:700;cursor:pointer;box-shadow:0 4px 16px #0005}
:is(#storyboard-ai-toolbar,#story-description-ai,#video-flow-ai)>summary::-webkit-details-marker{display:none}
:is(#storyboard-ai-toolbar,#story-description-ai,#video-flow-ai) .storyboard-ai-actions{position:absolute;right:0;bottom:54px;min-width:180px;padding:8px;background:#252039;border:1px solid #48405c;border-radius:9px;box-shadow:0 8px 24px #0006}
:is(#storyboard-ai-toolbar,#story-description-ai,#video-flow-ai):not([open]) .storyboard-ai-actions{display:none}
:is(#storyboard-ai-toolbar,#story-description-ai,#video-flow-ai) .storyboard-ai-actions>button{display:block;width:100%;text-align:left;margin:3px 0;white-space:nowrap}
#page:has(:is(#storyboard-ai-toolbar,#story-description-ai,#video-flow-ai)) .ai-prompt-assist{display:none!important}
body:not(.workspace-entry-mode) #save-board.storyboard-save-continue{width:100%;padding:14px 20px!important;min-height:48px!important;font-size:14px!important}

#page .storyboard-save-row{display:block;width:100%}
body:not(.workspace-entry-mode) #page #save-board.storyboard-save-continue{display:block;width:100%!important;max-width:none!important;box-sizing:border-box}


#video-audio-script textarea{min-height:240px;resize:vertical}
#video-audio-script .row{gap:8px;flex-wrap:wrap}

.ai-dialog-close{flex:none!important;margin-left:auto;width:28px!important;height:28px;min-height:28px!important;padding:0!important;font-size:20px!important;line-height:1!important}

/* Share the Image/Video studio grid, panel and form control styles. */
.audio-studio{margin:0;min-width:0}
.audio-studio .audio-workspace{align-items:start}
.audio-model-controls,.audio-line-controls,.audio-output-controls{display:grid;grid-template-columns:minmax(0,1fr);gap:16px}
.audio-studio #audio-form,.audio-studio label{min-width:0}
.audio-studio input,.audio-studio select{min-width:0}
.audio-line{border:1px solid var(--border);border-radius:8px;margin:0 0 16px;padding:12px;min-width:0;display:grid;gap:12px}
.audio-line legend{padding:0 8px;font-size:12px;font-weight:600}
.audio-line textarea{width:100%;resize:vertical;min-height:100px}
.audio-line [data-remove-line]{justify-self:start}
.audio-studio #add-audio-line{align-self:flex-start}
.audio-studio #audio-form>.row{flex-direction:column;align-items:stretch}
.audio-card audio{display:block;width:100%;margin:16px 0}
.audio-transcript{white-space:pre-wrap;overflow-wrap:anywhere}
.audio-card .actions{margin-top:14px}
.audio-card h3{overflow-wrap:anywhere}
.audio-studio #audio-job-status:empty{display:none}


.audio-speaker-tabs{display:flex;flex-wrap:wrap;gap:8px;margin:12px 0}
.audio-speaker-tabs [aria-pressed=true]{border-color:var(--accent,#ffdc24);color:var(--accent,#ffdc24);box-shadow:0 0 0 1px #ffdc2420}
[data-delivery-controls],[data-speaker-panel]{display:flex;flex-direction:column;gap:12px}
.audio-voice-row,.audio-turn-heading{display:flex;align-items:flex-end;gap:10px}
.audio-voice-row>label,.audio-turn-heading>label{flex:1;min-width:0}
.generation-dialog .audio-voice-preview{display:flex;align-items:center;gap:6px;min-height:36px;flex-shrink:0}
.generation-dialog [data-speaker-field=delivery]{min-height:90px}
.audio-direction-note{margin:0;line-height:1.5}
#audio-voice-preview-dialog{width:min(560px,calc(100vw - 32px))}
#audio-voice-preview-dialog textarea{min-height:100px}
#audio-voice-preview-dialog audio{width:100%}

/* Hide the empty review placeholder once a recording exists. */
.audio-studio [hidden]{display:none!important}
#audio-review-results{min-width:0}
#audio-gallery{min-width:0}
.audio-card-preview{aspect-ratio:16/9;background:#14112b;display:flex;align-items:center;justify-content:center;padding:48px 14px 14px;min-width:0}
.audio-card-preview audio{min-width:0;margin:0}
.audio-card .card-body{min-width:0}

#audio-workflow-canvas label,#audio-workflow-step label,#audio-workflow-step legend,#audio-workflow-step h2,#audio-workflow-preview h3{color:var(--accent,#ffdc24)}
.audio-workflow-flow{list-style:none;padding:0;margin:20px auto;max-width:680px;display:flex;flex-direction:column;gap:26px}
.audio-workflow-flow li{position:relative}.audio-workflow-flow li:not(:last-child)::after{content:'↓';position:absolute;left:50%;bottom:-24px;color:var(--accent,#ffdc24);font-size:18px}
.audio-workflow-node{width:100%;display:grid;grid-template-columns:32px 1fr;gap:5px 10px;text-align:left;padding:14px!important;border:1px solid #615476!important;border-radius:9px!important}
.audio-workflow-node>span{grid-row:span 2;color:var(--accent,#ffdc24)}.audio-workflow-node>small{grid-column:2;font-weight:400;opacity:.85}.audio-workflow-node:hover,.audio-workflow-node:focus-visible{border-color:var(--accent,#ffdc24)!important;color:var(--accent,#ffdc24)!important}
#audio-workflow-step,#audio-workflow-preview{width:min(640px,92vw);max-height:85vh;overflow:auto}#audio-workflow-step .row{flex-wrap:wrap}#audio-workflow-step .row>label{flex:1;min-width:150px}#audio-workflow-step [hidden]{display:none!important}#audio-workflow-step .audio-workflow-check{display:flex;flex-direction:row;gap:8px}#audio-workflow-step input[type=checkbox]{width:auto}#audio-workflow-step [data-news],#audio-workflow-step [data-book],#audio-workflow-step [data-settings],#audio-workflow-step [data-chapters],#audio-workflow-step fieldset{display:grid;gap:12px}

/* Identical structure, spacing and focus treatment across all generation studios. */
#page .grid:has(>.generation-form),#page .audio-workspace:has(>.generation-form){display:grid;grid-template-columns:minmax(290px,360px) minmax(0,1fr);gap:24px;align-items:start}
#page .generation-form{width:auto;min-width:0;padding:16px;display:flex;flex-direction:column;gap:14px;background:var(--panel,#24203e)}
.generation-section{border:1px solid var(--border,#454065);border-radius:8px;padding:12px;display:flex;flex-direction:column;gap:10px;min-width:0;box-shadow:none}
.generation-section.is-focused{border-color:var(--accent,#ffdc24);box-shadow:0 0 0 1px #ffdc2420}
.generation-section-heading{font-size:13px;font-weight:600;color:var(--accent,#ffdc24)}
.generation-form label,.generation-dialog label{display:flex;flex-direction:column;gap:7px;font-size:12px;min-width:0}
.generation-form button,.generation-dialog button{min-height:30px;padding:6px 10px;font-size:12px;line-height:1.3;width:auto}
.generation-form input,.generation-form select,.generation-dialog input,.generation-dialog select{width:100%;min-width:0;box-sizing:border-box;min-height:36px;font-size:12px}
.generation-section [data-model]>label{font-size:0;gap:0}
.generation-action{text-align:left}
.generation-settings{padding:0;border:0;background:transparent;box-shadow:none}
.generation-settings>summary{list-style:none;display:flex;justify-content:space-between;align-items:center;padding:4px 0;cursor:pointer;font-size:12px;color:var(--muted,#b8b0cd)}
.generation-settings>summary::-webkit-details-marker{display:none}
.generation-settings>summary::after{content:'⌄';font-size:16px}
.generation-settings[open]>summary::after{transform:rotate(180deg)}
.generation-references>summary{font-size:13px;font-weight:600;color:var(--accent,#ffdc24)}
.generation-settings-body{display:flex;flex-direction:column;gap:12px;padding-top:12px}
.generation-settings:not([open])>.generation-settings-body{display:none}
.generation-selected,.generation-reference-tabs{display:flex;flex-wrap:wrap;gap:9px}
.generation-selected:empty{display:none}
.generation-selected-item{position:relative}
.generation-form .generation-thumb,.generation-dialog .generation-thumb{display:flex;flex-direction:column;align-items:center;padding:5px;width:70px;gap:4px;border:1px solid var(--border,#454065);border-radius:7px;background:transparent;color:var(--muted)}
.generation-thumb :is(img,video){width:56px;height:48px;object-fit:cover;border-radius:4px}
.generation-thumb span{font-size:10px;line-height:1.2}
.generation-form .generation-remove{position:absolute;right:-5px;top:-5px;border-radius:50%;padding:0;width:18px;min-height:18px;height:18px;font-size:13px;background:#38305e}
.generation-dialog [aria-pressed=true],.generation-form .generation-selected .generation-thumb{border-color:var(--accent,#ffdc24);color:var(--accent,#ffdc24);box-shadow:0 0 0 1px #ffdc2420}
.generation-prompt-summary{overflow-wrap:anywhere;white-space:pre-wrap;line-height:1.5;margin:0}
.generation-footer{display:flex;flex-direction:column;gap:8px}
.generation-footer>button{width:100%}
.generation-footer>[role=status]:empty{display:none}
.generation-dialog{width:min(660px,calc(100vw - 32px));max-height:85vh;overflow:auto;padding:20px;border:1px solid #605679;border-radius:12px;background:#201b32;color:#eeebf5}
.generation-dialog::backdrop{background:#0009}
.generation-dialog .form{gap:16px}
.generation-dialog [data-body],.generation-dialog [data-object-controls]{display:flex;flex-direction:column;gap:16px}
.generation-dialog textarea{width:100%;min-height:160px;resize:vertical;font-size:13px;line-height:1.5;box-sizing:border-box}
#generation-prompt-dialog textarea{max-height:none;overflow-y:hidden;resize:none}
.generation-ai-actions{display:flex;justify-content:flex-end;gap:8px;flex-wrap:wrap}
.generation-filter-row,.generation-attribute-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}
.generation-picker-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;max-height:50vh;overflow:auto}
.generation-dialog .generation-picker-item{display:flex;flex-direction:column;gap:6px;text-align:left;min-width:0;border:1px solid var(--border);background:transparent;padding:8px}
.generation-picker-item :is(img,video){width:100%;height:110px;object-fit:cover;border-radius:4px}
.generation-picker-item span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;width:100%}
.generation-picker-item small{font-size:10px;color:var(--muted)}
.generation-picker-item[aria-pressed=true] small{color:var(--accent)}
.generation-delivery{border:1px solid var(--border);border-radius:8px;padding:12px;margin:0 0 12px}
.generation-delivery .audio-line-controls{grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}
.generation-dialog .section-head{margin:0;align-items:center}
.generation-dialog .section-head h2{margin:0;font-size:18px}
.generation-dialog [hidden],.generation-form [hidden]{display:none!important}
@media(max-width:850px){#page .grid:has(>.generation-form),#page .audio-workspace:has(>.generation-form){grid-template-columns:1fr}}
@media(max-width:480px){.generation-filter-row,.generation-attribute-grid,.generation-delivery .audio-line-controls{grid-template-columns:1fr}.generation-picker-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}



/* Shared duration styling in model settings and shot controls. */
label:has(>[data-video-seconds]),label:has(>[data-setting="max_clip_seconds"]),label:has(>[data-seconds]){color:#d1cbe7;font-size:12px;font-weight:400;line-height:1.5;gap:7px}
input:is([data-video-seconds],[data-setting="max_clip_seconds"],[data-seconds]){color:#edf2ec;background:#1b1839;border:1px solid #51496f;border-radius:6px;padding:10px 12px;font-size:12px;min-height:36px}

body>aside #workspace-library-group details:has(>.library-more){position:relative}
body>aside #workspace-library-group .library-has-menu{position:relative;padding-right:30px!important}
body>aside #workspace-library-group .library-more{position:absolute!important;right:0!important;top:2px!important;left:auto!important;width:26px!important;min-width:26px!important;height:28px!important;min-height:0!important;padding:0!important;border:0!important;background:transparent!important;color:#fff!important;font-size:22px!important;line-height:26px!important;z-index:3}
body>aside #workspace-library-group .library-more::before{display:none!important}
body>aside #workspace-library-group .library-more:hover{background:#302a54!important}
.library-options-menu{position:fixed;z-index:10000;min-width:150px;padding:5px;border:1px solid #514b69;border-radius:7px;background:#201c30;box-shadow:0 8px 24px #0008}
.library-options-menu button{display:block;width:100%;text-align:left;color:white;background:transparent;padding:8px 12px}
.library-options-menu button:hover,.library-options-menu button:focus-visible{background:#38305e}
.library-rename-dialog{width:min(420px,calc(100vw - 32px))}.library-rename-dialog [role=alert]{color:#ff7272}

#object-editor-dialog{width:min(1280px,96vw);max-width:96vw;max-height:94vh;padding:22px;overflow:auto}
.oe-header,.oe-footer{display:flex;justify-content:space-between;align-items:center;gap:16px}
.oe-header h2{margin:5px 0 18px}.oe-layout{display:grid;grid-template-columns:minmax(0,1fr) 330px;gap:22px}
.oe-preview{min-width:0}.oe-controls{max-height:69vh;overflow:auto;padding-right:10px}
.oe-controls h3{margin:0 0 8px}.oe-section{border-top:1px solid var(--border);padding-top:18px;margin-top:12px}
.oe-toolbar{display:flex;gap:10px;align-items:end;flex-wrap:wrap;margin:10px 0}
.oe-toolbar label{font-size:12px;flex:1;min-width:100px}.oe-toolbar select{width:100%}
.oe-toolbar input[type=range]{width:100%}.oe-canvas-wrap{max-height:58vh;overflow:auto;background:#100e21;border:1px solid #4b4566;border-radius:10px;display:grid;place-items:start center;min-height:180px}
#oe-canvas{display:block;width:100%;height:auto;touch-action:none;cursor:crosshair}
#oe-canvas.oe-zoom-one{width:auto;max-width:none}#oe-canvas.oe-zoom-two{width:200%;max-width:none}
.oe-check{display:flex!important;gap:8px;align-items:center;white-space:nowrap}.oe-check input{width:auto}
.oe-controls input[type=color]{width:100%;height:36px;padding:3px}.oe-controls input[type=range]{width:100%}
.oe-endpoints{display:flex;justify-content:space-between;font-size:11px;color:#b9b5cc;margin-top:-7px}
.oe-footer{position:sticky;bottom:-22px;background:#242147;border-top:1px solid var(--border);padding:14px 0;margin-top:15px}
#oe-status{font-size:13px;color:#7de5d2;min-height:20px}
#oe-shade{accent-color:#b9b5cc}#oe-ai-fields{display:grid;gap:12px}
@media(max-width:900px){.oe-layout{grid-template-columns:1fr}.oe-controls{max-height:none}.oe-canvas-wrap{max-height:50vh}.oe-footer{position:static}}

dialog{position:fixed}
dialog.ecco-popup-close-ready{padding-top:44px!important}
:is(#ecco-error-popup,dialog).ecco-popup-close-ready > button.ecco-popup-close{
 position:absolute!important;top:10px!important;right:10px!important;
 width:26px!important;height:26px!important;min-width:26px!important;min-height:26px!important;
 max-width:26px!important;padding:0!important;margin:0!important;
 display:grid!important;place-items:center!important;border:0!important;border-radius:5px!important;
 background:#ffdc24!important;color:#211b33!important;font-size:20px!important;
 font-weight:600!important;line-height:1!important;box-shadow:none!important;cursor:pointer;z-index:20;
}
dialog .ecco-popup-close:focus-visible{outline:2px solid white!important;outline-offset:2px}
dialog [data-ecco-replaced-close]{display:none!important}

