 #activity-panel[hidden]{display:block!important;transform:translateX(100%);visibility:hidden;pointer-events:none}
 #activity-edge-arrow{position:fixed;right:0;top:50%;transform:translateY(-50%);z-index:91;width:40px;height:64px;padding:0;border-radius:10px 0 0 10px;font-size:25px;background:#38305e;color:#eeebf5;border:1px solid #70658c;transition:right .25s ease}
 #activity-edge-arrow.drawer-open{right:min(480px,calc(100vw - 48px))}
 body.workspace-entry-mode #activity-edge-arrow,body.workspace-entry-mode #activity-panel{display:none!important}
 @media(prefers-reduced-motion:reduce){#activity-panel,#activity-edge-arrow{transition:none}}


#image-scene-controls{margin:12px 0;padding:14px;border:1px solid #454065;border-radius:8px;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;min-width:0}
#image-scene-controls legend{font-size:14px;padding:0 6px;color:#eeebf5}
#image-scene-controls .help{grid-column:1/-1;margin:0;font-size:12px}
#image-scene-controls label{min-width:0;margin:0}
#image-scene-controls input{box-sizing:border-box;width:100%;min-width:0}
#image-prompt-preview{margin:8px 0 16px;font-size:12px}
#image-prompt-preview summary{cursor:pointer;color:#c8c1dc}
#image-effective-prompt{box-sizing:border-box;width:100%;margin-top:8px;font-size:12px;line-height:1.5}
#activity-page-toolbar{display:flex;justify-content:flex-end;align-items:center;min-height:30px;margin:0 0 8px;clear:both}
#activity-page-toolbar #activity-edge-arrow,#activity-page-toolbar #toggle-activity.activity-edge-toggle{position:static;transform:none;right:auto;top:auto;width:30px;height:30px;min-width:30px;padding:0;border-radius:6px;font-size:19px;line-height:1;background:#38305e;color:#eeebf5;border:1px solid #70658c;box-shadow:none;transition:background .15s;z-index:auto}
@media(max-width:600px){#image-scene-controls{grid-template-columns:1fr}}

.video-publish-row{display:flex;align-items:center;gap:4px}.video-publish-choice{display:flex;align-items:center;gap:8px;flex:1;min-width:0;font-size:12px;padding:8px 4px;cursor:pointer;margin:0}.video-publish-choice input[type=radio]{width:15px;height:15px;flex:0 0 15px;accent-color:#f3dc45;margin:0}.video-publish-choice span{overflow-wrap:anywhere}.video-publish-row>.workspace-delete{opacity:0}.video-publish-row:hover>.workspace-delete,.video-publish-row:focus-within>.workspace-delete{opacity:1}#workspace-youtube-row{border-top:1px solid #454065;margin-top:8px;padding-top:10px}#workspace-youtube:disabled{opacity:.5;cursor:not-allowed}
.workspace-library>summary>.library-symbol{color:var(--accent,#f3dc45)}
.workspace-library[open]>summary>.library-symbol{color:#fff}
.tree-branch-toggle[aria-expanded="false"]{color:var(--accent,#f3dc45)}
.tree-branch-toggle[aria-expanded="true"]{color:#fff}

.image-control-section{border:1px solid #454065;border-radius:8px;margin:0 0 12px}.image-control-section>summary{display:list-item;cursor:pointer;padding:12px;font-size:14px;font-weight:600;color:#eeebf5}.image-control-section>summary::marker{color:var(--accent,#ffdc24)}.image-control-section[open]>summary::marker{color:#fff}.image-control-body{padding:0 12px 12px;display:flex;flex-direction:column;gap:10px}.image-control-section:not([open])>.image-control-body{display:none}.image-control-body>#image-scene-controls{margin:0;padding:8px;grid-template-columns:1fr}.image-control-body>#image-scene-controls>legend{display:none}
#activity-page-toolbar #activity-edge-arrow,#activity-page-toolbar #toggle-activity.activity-edge-toggle{color:var(--accent,#ffdc24)}

#image-form #edit-model-settings,#video-form #edit-model-settings{display:none!important}

.scene-controls-dialog{width:min(620px,90vw);max-height:85vh;overflow:auto;border:1px solid #605679;border-radius:12px;background:#201b32;color:#eeebf5;padding:20px}.scene-controls-dialog::backdrop{background:#0009}.scene-controls-dialog #image-scene-controls{display:grid;grid-template-columns:1fr 1fr;gap:12px}.scene-controls-dialog #image-scene-controls>p,.scene-controls-dialog #image-scene-controls>legend{grid-column:1/-1}.scene-controls-dialog .form{gap:12px}.activity-working-dots,.job-working-dots{display:inline-block;overflow:hidden;width:1.15em;vertical-align:bottom;animation:ecco-working-dots 1.2s steps(4,end) infinite;color:var(--accent,#ffdc24)}#activity-page-toolbar #activity-edge-arrow.has-active-jobs{width:58px}.ai-prompt-assist{align-self:flex-end;color:var(--accent,#ffdc24)}@keyframes ecco-working-dots{0%{clip-path:inset(0 100% 0 0)}100%{clip-path:inset(0 0 0 0)}}@media(prefers-reduced-motion:reduce){.activity-working-dots,.job-working-dots{animation:none}}@media(max-width:600px){.scene-controls-dialog #image-scene-controls{grid-template-columns:1fr}}

/* Welcome-page logo only: colored objects travel straight from the center outward, without rotation. */
:is(#workspace-entry,#story-choice-screen) .entry-logo-motion{position:relative;width:156px;height:156px;margin:0 0 24px;isolation:isolate}
:is(#workspace-entry,#story-choice-screen) .entry-logo-motion .entry-logo{position:absolute;inset:0;width:156px;height:156px;margin:0;clip-path:circle(14% at 50% 50%);z-index:2}
:is(#workspace-entry,#story-choice-screen) .entry-logo-particle{position:absolute;left:calc(50% - 4px);top:calc(50% - 4px);width:8px;height:8px;border-radius:50%;background:var(--particle-color);opacity:0;animation:ecco-logo-outbound 4s linear infinite;animation-delay:var(--particle-delay);animation-play-state:paused;pointer-events:none}
body.workspace-entry-mode :is(#workspace-entry,#story-choice-screen) .entry-logo-particle{animation-play-state:running}
@keyframes ecco-logo-outbound{0%{transform:translate(0,0) scale(.15);opacity:0}10%{opacity:1}75%{opacity:1}100%{transform:translate(var(--ray-x),var(--ray-y)) scale(1.15);opacity:0}}
@media(prefers-reduced-motion:reduce){:is(#workspace-entry,#story-choice-screen) .entry-logo-motion .entry-logo{clip-path:none}:is(#workspace-entry,#story-choice-screen) .entry-logo-particle{display:none;animation:none}}

