.tree-image{display:flex!important;align-items:center;gap:8px}.tree-image img{width:40px;height:40px;object-fit:cover;border-radius:5px;flex-shrink:0}.tree-image span{overflow:hidden;text-overflow:ellipsis}.card.library-highlight{outline:2px solid var(--accent,#ffdc24);outline-offset:3px}

.library-view-label{display:flex;align-items:center;gap:8px;font-size:12px}.library-view-label select{width:auto;min-width:125px}#library-gallery.library-view-small{display:grid;grid-template-columns:repeat(auto-fill,minmax(165px,1fr));gap:12px}#library-gallery.library-view-large{display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:18px}#library-gallery.library-view-list{display:flex;flex-direction:column;gap:8px}#library-gallery.library-view-small .card>img{height:120px;width:100%;object-fit:contain}#library-gallery.library-view-large .card>img{height:280px;width:100%;object-fit:contain}#library-gallery.library-view-list .card{display:grid;grid-template-columns:80px minmax(0,1fr);align-items:center;min-height:85px;padding:8px;position:relative}#library-gallery.library-view-list .card>img{width:72px;height:72px;object-fit:contain}#library-gallery.library-view-list .card-body{padding:4px 70px 4px 12px}#library-gallery.library-view-small .card-body{padding:10px;font-size:12px}#library-gallery.library-view-list .card-body>.help,#library-gallery.library-view-small .card-body>.help{display:none}#library-gallery .library-card-actions>summary{cursor:pointer;color:var(--accent,#ffdc24);font-size:12px;margin-top:8px}#library-gallery .library-card-actions:not([open])>.actions{display:none}#library-gallery.library-view-large .library-card-actions>.actions{display:flex}#library-gallery.library-view-large .library-card-actions>summary{display:none}

