.project>.workspace-library:not([open])>summary,.project>.workspace-library:not([open])>summary>span:not(.library-symbol){color:#fff!important}.project>.workspace-library[open]>summary>span:not(.library-symbol){color:var(--accent,#ffdc24)!important}

#workspace-copyright,#workspace-entry .entry-copyright{color:var(--accent,#ffdc24)!important}

#workspace-trash,#workspace-copyright,#workspace-entry .entry-copyright{color:#fff!important}

/* Activity drawer uses the navigation palette and compact controls. */
#activity-panel{background:#201d44;color:#eeebf5;border-left:1px solid #45405e;padding:20px}
#activity-panel button{width:auto;min-width:0;min-height:30px;padding:6px 10px;font-size:12px;line-height:1.4;flex:0 0 auto}
#activity-panel #ecco-activity-tabs{display:flex;justify-content:flex-start;gap:8px;margin:12px 0}
#activity-panel #ecco-activity-tabs button{flex:0 0 auto;width:auto}
#activity-panel #close-activity{width:30px;height:30px;padding:0;font-size:18px}

/* Six-step story creation journey. */
#workspace-production-group.story-journey{margin-top:20px}
.story-journey>h2{font-size:14px;font-weight:600;margin:0 0 10px;padding:0 10px;color:var(--text,#eeebf5)}
.story-journey>.workspace-library-content{padding:0;border:0}
#workspace-production-group .journey-step{display:block;width:100%;text-align:left;font-size:12px;line-height:1.5;padding:9px 10px;border-radius:6px;margin:3px 0;background:transparent;color:var(--muted,#b8b4c5)}
#workspace-production-group .journey-step.active{background:var(--accent,#ffdc24);color:#191720}
#journey-guide{display:flex;justify-content:space-between;align-items:center;gap:18px;border-bottom:1px solid #ffffff18;padding:4px 0 18px;margin-bottom:20px}
#journey-guide[hidden]{display:none}
#journey-guide small{font-size:10px;letter-spacing:.12em;color:var(--accent,#ffdc24)}
#journey-guide h2{font-size:20px;margin:5px 0}
#journey-guide p{font-size:12px;line-height:1.6;color:var(--muted,#b8b4c5);margin:0;max-width:620px}
.journey-actions{display:flex;gap:8px;flex-wrap:wrap;justify-content:flex-end}
.journey-actions button{font-size:12px;padding:7px 10px}
@media(max-width:800px){#journey-guide{align-items:flex-start;flex-direction:column}.journey-actions{justify-content:flex-start}}

/* Library creation controls use the same compact type as label rows. */
#workspace-library-group .tree-create{font-size:12px!important;font-weight:400!important;line-height:1.5!important;padding:7px 10px!important;min-height:0!important}
#workspace-library-group .tree-create :is(span,i,svg){font-size:inherit!important;width:1em;height:1em}
#workspace-library-group .tree-create::before,#workspace-library-group .tree-create::after{font-size:inherit!important}

#page .section-head .row>button,#page .library-view-label,#page .library-view-label select{font-size:12px!important;font-weight:400!important;min-height:30px;padding:6px 10px!important;width:auto}

/* Shared compact button sizing across Studios menus and action toolbars. */
body:not(.workspace-entry-mode) :is(#workspace-menus button,#workspace-menus .workspace-menu>summary,#workspace-library-group button,#workspace-production-group button,main button,dialog button){
 font-size:12px!important;line-height:18px!important;font-weight:500!important;min-height:32px!important;padding:6px 10px!important;box-sizing:border-box;
}
body:not(.workspace-entry-mode) :is(.asset-icon,.workspace-delete,.storage-key-toggle,.tree-branch-toggle){width:32px!important;min-width:32px!important;height:32px!important;padding:6px!important}
body:not(.workspace-entry-mode) :is(.asset-icon,.workspace-delete,.storage-key-toggle) svg{width:16px!important;height:16px!important}
#workspace-menus .workspace-menu>summary{display:flex;align-items:center}

#page .section-head>.row{display:flex!important;align-items:flex-end!important;gap:10px;flex-wrap:wrap}#page .section-head>.row>button{height:32px!important;min-height:32px!important;white-space:nowrap!important;flex:0 0 auto;align-self:flex-end}#page .library-view-label{padding:0!important;margin:0}

/* Uniform yellow feedback for pressed, focused and selected actions. */
body:not(.workspace-entry-mode) button:not(:disabled):is(:active,:focus,.active,.selected,[aria-pressed="true"],[aria-selected="true"]){color:var(--accent,#ffdc24)!important;background:#38305e!important}
body:not(.workspace-entry-mode) summary:is(:active,:focus-visible),body:not(.workspace-entry-mode) details[open]>summary{color:var(--accent,#ffdc24)!important}

/* One button-shaped library toolbar: layout, upload, new label. */
#page .section-head label.library-view-label{font-size:0!important;line-height:0!important;padding:0!important;margin:0!important;min-height:32px!important;display:block}
#page .section-head .library-view-label select,#page .section-head>.row>button{
 width:128px!important;min-width:128px!important;max-width:128px!important;height:32px!important;min-height:32px!important;
 padding:6px 10px!important;margin:0!important;font-size:12px!important;line-height:18px!important;font-weight:500!important;
 color:var(--accent,#ffdc24)!important;background:rgba(255,220,36,.12)!important;border:1px solid rgba(255,220,36,.28)!important;border-radius:6px!important;box-sizing:border-box;white-space:nowrap!important;
}
#page .section-head .library-view-label select option{background:#211d3b;color:#eeebf5}
#page .section-head>.row>button:hover,#page .section-head .library-view-label select:hover{background:rgba(255,220,36,.2)!important}

/* Library toolbar labels stay white; retain the shared yellow shading. */
body:not(.workspace-entry-mode) #page .section-head .library-view-label select,
body:not(.workspace-entry-mode) #page .section-head>.row>button,
body:not(.workspace-entry-mode) #page .section-head>.row>button:is(:active,:focus,:hover){
 color:#fff!important;
}
#journey-publish{margin-top:20px}

/* Match library navigation to the production workflow. */
#workspace-library-group>.workspace-library-content{display:flex;flex-direction:column}
#workspace-library-group>.workspace-library-content>.project{order:1}
#workspace-library-group>.workspace-library-content>#image-library-nav{order:2}
#workspace-library-group>.workspace-library-content>#workspace-audio-library{order:3}
#workspace-library-group>.workspace-library-content>#workspace-video-library{order:4}
aside>#workspace-trash{margin-left:auto;align-self:flex-end}
/* Shared library overview modes. */
#video-library-gallery.library-list{display:flex;flex-direction:column}
#video-library-gallery.library-list .card{width:100%}
#video-library-gallery.library-list video{max-height:100px}
#video-library-gallery.library-small{grid-template-columns:repeat(auto-fill,minmax(180px,1fr))}
#video-library-gallery.library-large{grid-template-columns:repeat(auto-fill,minmax(320px,1fr))}
#story-library-list.library-small,#story-library-list.library-large{display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr))}
#story-library-list.library-large{grid-template-columns:repeat(auto-fill,minmax(300px,1fr))}

/* Library creation and upload actions belong in the main toolbar. */
#workspace-library-group .tree-create,#workspace-library-group .tree-upload,#workspace-library-group .workspace-upload,#workspace-library-group #library-new-folder{display:none!important}

/* Subtle separation above the navigation copyright. */
#workspace-copyright{border-top:1px solid rgba(255,255,255,.10);padding-top:12px}

/* Neutral educational content, square task checkboxes and spaced guide note. */
.education-guide .panel,.education-guide .panel>summary,.education-guide .panel p{background:transparent!important}
.education-guide .panel>summary{color:#eeebf5!important}
.education-guide>.help:last-child{color:var(--accent,#ffdc24)!important;text-align:right;margin-top:24px;padding-top:8px}
#development-planner input[type=checkbox],#learning-days input[type=checkbox]{appearance:auto!important;-webkit-appearance:checkbox!important;width:16px!important;min-width:16px!important;height:16px!important;min-height:16px!important;border-radius:2px!important;padding:0!important;accent-color:var(--accent,#ffdc24);flex:0 0 16px}
#learning-days{border-top:1px solid rgba(255,255,255,.12);margin-top:12px;padding-top:12px}
#education-menu .education-content{max-height:75vh;overflow-y:auto;min-width:320px}
#learning-days .learning-day-items{padding-left:24px}
#learning-days .learning-day-items li{display:list-item;margin:8px 0}
#learning-days [data-day-text]{width:calc(100% - 30px);display:inline-block;margin-left:8px;font-size:12px}
#learning-days label{font-size:12px}
#learning-days input,#learning-days select{min-height:32px;font-size:12px}
#education-menu #checklist[hidden],#education-menu h3[hidden]{display:none!important}

/* Compact PDF importer and selectable page preview. */
#story-pdf-tools{padding:8px 0;border-bottom:1px solid rgba(255,255,255,.12)}
#story-pdf-tools button,.pdf-story-dialog button{font-size:12px!important;min-height:28px!important;padding:4px 9px!important;width:auto!important}
#story-pdf-tools summary,#story-pdf-tools .help,#story-pdf-tools [data-filename]{font-size:12px}
.pdf-story-dialog{width:min(950px,94vw);max-height:92vh;overflow:auto;padding:16px;background:#201d44;color:#eeebf5;border:1px solid #45405e;border-radius:8px}
.pdf-dialog-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:10px}
.pdf-page-controls{align-items:center;gap:8px}.pdf-page-controls label{display:flex;align-items:center;gap:6px;font-size:12px}
.pdf-page-controls select{width:66px;min-height:28px;padding:4px;font-size:12px}
.pdf-story-dialog .help{font-size:12px;margin:8px 0}
.pdf-page-scroll{height:48vh;overflow:auto;background:#131126;padding:12px;border-radius:6px}
.pdf-story-page{position:relative;margin:0 auto;background:white;--scale-round-x:1px;--scale-round-y:1px}
.pdf-story-page canvas{display:block}
.pdf-story-page .textLayer{position:absolute;inset:0;overflow:clip;line-height:1;text-align:initial;user-select:text}
.pdf-story-page .textLayer span,.pdf-story-page .textLayer br{position:absolute;color:transparent;white-space:pre;transform-origin:0 0;cursor:text}
.pdf-story-page .textLayer ::selection{background:rgba(255,214,0,.45)}
.pdf-selected-label{display:block;font-size:12px;margin-top:10px}
.pdf-selected-label textarea{width:100%;font-size:12px;min-height:70px}

/* Education follows the same compact disclosure pattern as Library. */
#education-menu .education-tree{padding:0;margin:4px 0;border:0;background:transparent}
#education-menu .education-tree>summary{display:flex;align-items:center;gap:8px;padding:7px 4px;font-size:12px;background:transparent!important;color:#eeebf5!important;list-style:none;cursor:pointer}
#education-menu .education-tree>summary::-webkit-details-marker,#education-menu .learning-day>summary::-webkit-details-marker{display:none}
#education-menu .education-tree>summary::before{content:'+';color:var(--accent,#ffdc24);width:12px}
#education-menu .education-tree[open]>summary::before{content:'−'}
#education-menu .education-tree-body{padding:0 0 0 18px}
#education-menu .education-tree button,#education-menu .education-tree button:is(:hover,:focus,:active){background:transparent!important;border:0!important;box-shadow:none!important;color:#eeebf5!important;font-size:12px!important;text-align:left;padding:5px 4px!important;width:auto}
#education-menu .education-tree-body>button{display:block;width:100%;white-space:normal}
#education-menu .learning-day{border:0;background:transparent;margin:5px 0}
#education-menu .learning-day>summary{list-style:none;background:transparent!important;color:#eeebf5!important;font-size:12px;padding:5px 0;cursor:pointer}
#education-menu .learning-activities{padding-left:12px}
#learning-days{border-top:0;margin-top:4px;padding-top:0}
#learning-days .learning-task{display:flex;align-items:center;gap:8px;margin:5px 0;padding:0;font-size:12px;line-height:20px}
#learning-days .learning-task span{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#learning-days .learning-task input:checked+span,#development-planner input[type=checkbox]:checked+span{text-decoration:line-through;opacity:.55}
#learning-days .learning-add-task{display:flex;align-items:center;gap:5px;margin:7px 0}
#learning-days .learning-add-task input{min-width:0;flex:1;width:160px}
#learning-days .learning-rename{font-size:10px;opacity:.75}
#learning-days .learning-rename input{display:inline-block;width:140px;margin-left:8px}

/* Checklist text stays compact; editing appears only when selected. */
#education-menu #learning-days .learning-task-text{flex:1;min-width:0;padding:0!important;font-weight:400;line-height:20px;white-space:normal;overflow-wrap:anywhere}
#education-menu #learning-days .learning-task-text:hover{text-decoration:underline}
#learning-days .learning-task input:checked+.learning-task-text{text-decoration:line-through;opacity:.55}
#learning-days .learning-task [data-day-text]{flex:1;min-width:0;width:100%;margin:0}
#learning-days [hidden]{display:none!important}

/* Keep checklist rows inline and match the library expansion highlight. */
#learning-days .learning-task{flex-direction:row;flex-wrap:nowrap;align-items:center}
#learning-days .learning-task input[type=checkbox]{margin:0;align-self:center}
#education-menu #learning-days .learning-task-text{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#education-menu .education-tree>summary,#education-menu .learning-day>summary{display:flex;align-items:center;gap:8px;padding:7px 10px;border-radius:7px}
#education-menu .education-tree>summary::before,#education-menu .learning-day>summary::before{content:'+';width:12px;flex:0 0 12px;color:inherit}
#education-menu .education-tree[open]>summary,#education-menu .learning-day[open]>summary{background:#38305e!important;color:var(--accent,#ffdc24)!important;box-shadow:inset 3px 0 var(--accent,#ffdc24)!important;border-radius:7px}
#education-menu .education-tree[open]>summary::before,#education-menu .learning-day[open]>summary::before{content:'−';color:var(--accent,#ffdc24)}

#education-menu .learning-day>summary{display:flex;align-items:center;gap:6px}
#education-menu .learning-day>summary>span{flex:1;min-width:0}
#education-menu .education-tree .learning-day-menu{margin-left:auto;width:24px!important;min-width:24px!important;min-height:24px!important;height:24px;padding:0!important;font-size:18px!important;text-align:center;line-height:24px}
#learning-rename-dialog{width:min(360px,90vw);background:#201d44;color:#eeebf5;border:1px solid #45405e;border-radius:8px}

/* Account, Activity and Billing share Library's interaction shading. */
#workspace-menus .workspace-menu:is([data-category="Account"],[data-category="Activity"],[data-category="Billing"])>summary:hover{background:#302a54}
#workspace-menus .workspace-menu:is([data-category="Account"],[data-category="Activity"],[data-category="Billing"])[open]>summary,
#workspace-menus .workspace-menu:is([data-category="Account"],[data-category="Activity"],[data-category="Billing"])>summary:is(:active,:focus-visible){background:#38305e;color:var(--accent,#ffdc24)!important;box-shadow:inset 3px 0 var(--accent,#ffdc24);border-radius:7px}

/* Education and Learning matches the other ribbon headings. */
#workspace-menus #education-menu>summary:hover{background:#302a54}
#workspace-menus #education-menu[open]>summary,
#workspace-menus #education-menu>summary:is(:active,:focus-visible){background:#38305e;color:var(--accent,#ffdc24)!important;box-shadow:inset 3px 0 var(--accent,#ffdc24);border-radius:7px}

/* Shared interaction treatment for every top-ribbon action. */
.workspace-ribbon :is(button,.workspace-menu>summary){border-radius:7px}
.workspace-ribbon :is(button:not(:disabled),.workspace-menu>summary):hover{background:#302a54!important}
.workspace-ribbon button:not(:disabled):is(:active,:focus-visible,.active,.selected,[aria-pressed="true"],[aria-expanded="true"]),
.workspace-ribbon .workspace-menu[open]>summary,
.workspace-ribbon .workspace-menu>summary:is(:active,:focus-visible){background:#38305e!important;color:var(--accent,#ffdc24)!important;box-shadow:inset 3px 0 var(--accent,#ffdc24)!important;border-radius:7px}

/* Let readers resize the PDF preview within the browser viewport. */
.pdf-story-dialog{resize:both;overflow:auto;min-width:min(360px,94vw);min-height:300px;max-width:96vw;max-height:94vh}
.pdf-story-dialog[open]{display:flex;flex-direction:column;height: min(820px,90vh)}
.pdf-story-dialog .pdf-page-scroll{flex:1 1 auto;min-height:140px;height:auto}
.pdf-story-dialog>.pdf-dialog-head,.pdf-story-dialog>.pdf-selected-label,.pdf-story-dialog>.row{flex-shrink:0}

/* Custom story types are edited within the dropdown. */
.story-type-dropdown{position:relative;font-size:12px}
.story-type-dropdown>summary{cursor:pointer;padding:9px 12px;border:1px solid #45405e;border-radius:6px;background:#252039;color:#eeebf5}
.story-type-options{position:absolute;left:0;right:0;top:100%;z-index:30;padding:8px;background:#252039;border:1px solid #605679;border-radius:6px;box-shadow:0 10px 24px #0006}
.story-type-options [data-types]{max-height:220px;overflow:auto;display:flex;flex-direction:column}
.story-type-options [data-types]>button{text-align:left;background:transparent;color:#eeebf5;border:0}
.story-type-options [data-types]>button:hover{background:#38305e;color:var(--accent,#ffdc24)}
.story-type-options [data-custom-entry]{padding-top:8px;border-top:1px solid #45405e}
.story-type-options input{width:100%;box-sizing:border-box;font-size:12px}
.story-type-options .row{margin-top:8px;gap:8px}
.story-type-options [hidden],.story-type-dropdown:not([open])>.story-type-options{display:none!important}

/* Shared field-label color for Tell Your Story. */
#page.story-journey-fields label,
#page.story-journey-fields .ai-prompt-label{color:var(--accent,#ffdc24)!important}
#page.story-journey-fields label input,
#page.story-journey-fields label textarea,
#page.story-journey-fields label select{color:var(--text,#eeebf5)}

#workspace-menus [data-category="Billing"]>summary>span[aria-hidden="true"]{margin-left:auto}

/* Keep the scene count and duration together at the right edge. */
#scene-count-controls{justify-content:flex-end;align-items:flex-end;gap:12px;flex-wrap:nowrap}
#scene-count-controls>label{flex:0 0 auto}



/* Story and Workflow libraries share the other libraries' card and view sizes. */
#story-library-list,#workflow-library-list{gap:12px}
#story-library-list>h3,#workflow-library-list>h3{grid-column:1/-1;margin:12px 0 0}
.text-library-gallery.library-small{display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr))}
.text-library-gallery.library-large{display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr))}
.text-library-gallery.library-list,#story-library-list.library-list{display:flex;flex-direction:column}
.text-library-card{position:relative;overflow:hidden;min-width:0;border:1px solid #48405c;border-radius:9px;background:#252039}
.text-library-open{display:flex!important;flex-direction:column;align-items:stretch;width:100%;min-width:0;padding:0!important;border:0!important;background:transparent!important;color:inherit!important;text-align:left;box-shadow:none!important}
.text-library-preview{display:flex;align-items:center;justify-content:center;aspect-ratio:16/9;background:#14112b;color:#c6bbdf}
.text-library-preview svg{width:44px;height:44px}
.text-library-caption{display:flex;flex-direction:column;gap:5px;padding:12px 38px 12px 12px;min-width:0}
.text-library-caption strong{font-size:13px;line-height:1.4;font-weight:500;overflow-wrap:anywhere}
.text-library-caption small{font-size:11px;color:var(--muted,#b1acc9)}
.text-library-caption small:empty{display:none}
.text-library-delete{position:absolute!important;right:5px;top:5px;z-index:1}
.text-library-card:hover,.text-library-card:focus-within{border-color:var(--accent,#ffdc24)}
.library-large .text-library-preview svg{width:64px;height:64px}
.library-list .text-library-open{flex-direction:row;align-items:center}
.library-list .text-library-preview{width:72px;height:72px;aspect-ratio:auto;flex-shrink:0}
.library-list .text-library-preview svg{width:32px;height:32px}
.text-library-row{position:relative;min-width:0}
.text-library-row .text-library-open{flex-direction:row;align-items:center;gap:8px;padding:8px 34px 8px 6px!important;border-radius:5px}
.text-library-row .text-library-preview{width:18px;height:18px;aspect-ratio:auto;flex-shrink:0;background:transparent}
.text-library-row .text-library-preview svg{width:18px;height:18px}
.text-library-row .text-library-caption{padding:0}
.text-library-row .text-library-caption strong{font-size:12px;font-weight:400}
.text-library-row .text-library-delete{top:50%;transform:translateY(-50%);right:0}

#story-entry-panel{display:flex;align-items:center;flex-wrap:wrap;gap:12px}
.story-format-source{position:absolute!important;width:1px!important;height:1px!important;overflow:hidden!important;clip-path:inset(50%);white-space:nowrap}
.story-format-control{display:inline-flex;align-items:center;gap:12px;border:1px solid #554a6b;border-radius:9px;padding:7px 10px;background:#252039}
.story-format-control>span{font-size:12px;font-weight:500;white-space:nowrap}
.story-format-options{display:flex;gap:4px}
body:not(.workspace-entry-mode) .story-format-options>button{padding:6px 12px!important;min-height:30px!important;font-size:12px!important;border:1px solid transparent!important;border-radius:6px!important;background:transparent!important;color:#d8d3e4!important}
body:not(.workspace-entry-mode) .story-format-options>button.is-selected{border-color:var(--accent,#ffdc24)!important;color:var(--accent,#ffdc24)!important;background:#39304f!important}
.story-format-options>button:focus-visible{outline:2px solid var(--accent,#ffdc24);outline-offset:2px}

/* Match Image Library's small, large and list previews. */
#story-library-list.library-small{grid-template-columns:repeat(auto-fill,minmax(165px,1fr));gap:12px}
#story-library-list.library-large{grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:18px}
#story-library-list.library-small .text-library-preview{height:120px;aspect-ratio:auto}
#story-library-list.library-large .text-library-preview{height:280px;aspect-ratio:auto}
#story-library-list.library-list{gap:8px}
#story-library-list.library-list .card{min-height:85px;padding:8px}
#story-library-list.library-list .text-library-preview{width:72px;height:72px}
#story-library-list .text-library-preview{color:var(--accent,#ffdc24)}
#story-library-list .text-library-open:hover strong,#story-library-list .text-library-open:focus-visible strong{color:var(--accent,#ffdc24)}
.story-source-controls{display:inline-flex;align-items:center;gap:4px;border:1px solid #554a6b;border-radius:9px;padding:7px;background:#252039}
body:not(.workspace-entry-mode) .story-source-controls>button,.story-source-controls>.workspace-menu>summary{padding:6px 10px!important;min-height:30px!important;font-size:12px!important;box-sizing:border-box}
.story-source-controls>.workspace-menu>summary>span{font-size:11px}

/* One marker for every Library navigation item; main-area preview cards stay intact. */
#workspace-library-group .workspace-library>summary>.library-symbol,
#workspace-library-group .text-library-row .text-library-preview{display:none!important}
#workspace-library-group :is(.workspace-library>summary,.tree-folder,.tree-image,.text-library-open,.tree-create,.tree-upload,.video-publish-choice){position:relative;padding-left:26px!important}
#workspace-library-group :is(.workspace-library>summary,.tree-folder,.tree-image,.text-library-open,.tree-create,.tree-upload,.video-publish-choice)::before,
#workspace-library-group .tree-branch-toggle::before{content:'−';position:absolute;left:8px;top:50%;width:12px;height:18px;line-height:18px;font-size:17px;border-radius:0;color:var(--accent,#ffdc24);background:transparent;transform:translateY(-50%);pointer-events:none}
#workspace-library-group :is(.workspace-library[open]>summary,summary.active,.tree-folder.selected,.tree-image.selected,.tree-create:focus,.tree-upload:focus,.tree-folder:focus,.tree-image:focus,.video-publish-choice:has(input:checked))::before,
#workspace-library-group .tree-branch-row:has(.tree-folder.selected)>.tree-branch-toggle::before{background:var(--accent,#ffdc24)}
#workspace-library-group .text-library-row .text-library-open.selected{color:var(--accent,#ffdc24)!important}
#workspace-library-group .tree-branch-spacer{display:none}
#workspace-library-group .tree-branch-toggle{position:relative;width:26px!important;min-width:26px!important;flex-basis:26px;font-size:0!important}
#workspace-library-group .tree-branch-row:has(>.tree-branch-toggle)>.tree-folder,
#workspace-library-group .tree-branch-row:has(>.tree-branch-toggle)>.library-selected-row>.tree-folder{padding-left:0!important}
#workspace-library-group .tree-branch-row:has(>.tree-branch-toggle)>.tree-folder::before,
#workspace-library-group .tree-branch-row:has(>.tree-branch-toggle)>.library-selected-row>.tree-folder::before{display:none}
#workspace-library-group .video-publish-choice>input{position:absolute;width:1px!important;height:1px!important;clip-path:inset(50%);overflow:hidden}
#workspace-library-group .video-publish-choice:has(input:checked){color:var(--accent,#ffdc24)}
#workspace-library-group .video-publish-choice:has(input:focus-visible){outline:1px solid var(--accent,#ffdc24);outline-offset:2px}


/* Keep the parent disclosure separate and leave room between item bullets and labels. */
#workspace-library-group>summary::before{display:none}
body:not(.workspace-entry-mode) #workspace-library-group.workspace-library :is(.tree-folder,.tree-image,.text-library-open,.tree-create,.tree-upload,.video-publish-choice){padding-left:26px!important}
body:not(.workspace-entry-mode) #workspace-library-group .tree-branch-row:has(>.tree-branch-toggle)>.tree-folder,
body:not(.workspace-entry-mode) #workspace-library-group .tree-branch-row:has(>.tree-branch-toggle)>.library-selected-row>.tree-folder{padding-left:0!important}

/* Story choices precede workspace navigation. */
body.story-choice-mode{display:block}
body.story-choice-mode>aside{display:none!important}
body.story-choice-mode>main{margin-left:0!important;width:100%;max-width:none}
body.story-choice-mode>main>header{display:flex!important}
body.story-choice-mode #activity-edge-arrow,body.story-choice-mode #activity-panel{display:none!important}
#story-choice-screen{min-height:calc(100dvh - 64px);display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;gap:24px}
#story-choice-screen .story-choice-actions{display:flex;flex-direction:column;gap:12px;align-items:stretch;max-width:100%}
#story-choice-screen button{background:#302a54;color:#fff;font-size:12px;line-height:1.4;padding:7px 10px;min-height:30px;border-radius:6px;box-shadow:none}
#story-choice-screen button:hover{background:#38305e}
#story-choice-screen button:focus-visible{outline:2px solid white;outline-offset:3px}
#story-choice-screen .entry-logo-particle{animation-play-state:running}

/* Align the two primary sidebar disclosures and their label columns. */
body>aside :is(#workspace-library-group,#workspace-production-group).workspace-library>summary{
 display:flex!important;align-items:center;gap:10px!important;
 padding:10px 5px!important;margin:0!important;font-size:13px!important;
}
body>aside :is(#workspace-library-group,#workspace-production-group).workspace-library>summary::before{display:none!important}
body>aside :is(#workspace-library-group,#workspace-production-group).workspace-library>summary>.library-symbol{
 display:inline-block!important;position:static!important;flex:0 0 12px;width:12px;text-align:center;
}

/* Library categories and label contents use yellow signs instead of bullets. */
body>aside #workspace-library-group .workspace-library>summary>.library-symbol{display:none!important}
body>aside #workspace-library-group .workspace-library>summary::before,
body>aside #workspace-library-group .tree-branch-row::before,
body>aside #workspace-library-group [data-library-marker].tree-folder::before{
 content:'+'!important;display:block!important;position:absolute;left:8px;top:50%;
 transform:translateY(-50%);width:12px;height:18px;line-height:18px;
 font-size:17px;font-weight:400;text-align:center;border-radius:0;
 color:var(--accent,#ffdc24)!important;background:transparent!important;pointer-events:none;
}
body>aside #workspace-library-group .tree-branch-row{position:relative;padding-left:26px}
body>aside #workspace-library-group .tree-branch-row::before,
body>aside #workspace-library-group [data-library-marker].tree-folder::before{content:attr(data-library-marker)!important}
body>aside #workspace-library-group .tree-branch-row .tree-folder::before,
body>aside #workspace-library-group .tree-branch-toggle::before{display:none!important}
body>aside #workspace-library-group .tree-branch-row .tree-folder{padding-left:0!important}
body>aside #workspace-library-group .tree-branch-toggle{position:absolute;left:0;top:0;height:100%!important;width:26px!important;min-width:26px!important;padding:0!important;background:transparent!important;z-index:1}

/* No bullets in Library: leaf entries use a yellow minus. */
body>aside #workspace-library-group :is(.tree-folder,.tree-image,.text-library-open,.tree-create,.tree-upload,.video-publish-choice)::before{
 content:'−';width:12px;height:18px;line-height:18px;font-size:17px;font-weight:400;
 text-align:center;border-radius:0;color:var(--accent,#ffdc24)!important;background:transparent!important;
}
body>aside #workspace-library-group .tree-create::before{content:'+'}
body>aside #workspace-library-group .tree-branch-row .tree-folder::before{display:none!important}

/* Expanded branches show minus; collapsed branches show plus. */
body>aside #workspace-library-group .workspace-library[open]>summary::before{content:'−'!important}

body > #activity-edge-arrow{position:fixed;right:0;top:50%;width:34px;height:48px;min-width:34px;padding:0;border-radius:8px 0 0 8px;font-size:21px;color:var(--accent,#ffdc24);transform:translate(110%,-50%);opacity:0;pointer-events:none;transition:transform .2s ease,opacity .2s ease,right .25s ease}
body > #activity-edge-arrow.edge-near,body > #activity-edge-arrow.drawer-open,body > #activity-edge-arrow:focus-visible{transform:translate(0,-50%);opacity:1;pointer-events:auto}
body > #activity-edge-arrow.drawer-open{right:min(480px,calc(100vw - 48px))}
body > #activity-edge-arrow.has-active-jobs{width:56px}
@media(hover:none),(pointer:coarse){body > #activity-edge-arrow{transform:translate(0,-50%);opacity:.65;pointer-events:auto}body > #activity-edge-arrow.drawer-open{opacity:1}}
@media(prefers-reduced-motion:reduce){body > #activity-edge-arrow{transition:none}}
